# The 'flip-hits' with arbitrary a: find the actual axis by requiring flush adjacency (copy adjacent to pattern, no overlap).
def solve(n):
    gi,go=G[n+' input'],G[n+' output']
    h,w=len(gi),len(gi[0])
    P=[(i,j) for i in range(h) for j in range(w) if gi[i][j]==4]
    AD={(i,j) for i in range(h) for j in range(w) if go[i][j]==4 and gi[i][j]==0}
    Sp=set(P)
    # V-mirror copies: i -> a-i; requires min(a-maxi - (maxi? )) copy rows = [a-maxi .. a-mini]; flush adjacent above/below pattern rows [mini..maxi]: a-maxi == mini-1 or a-mini == maxi+1 => a=2*mini-1 or a=2*maxi+1
    cands=[]
    for a in [2*min(i for i,_ in P)-1, 2*max(i for i,_ in P)+1]:
        Q={(a-i,j) for i,j in P}
        if Q&Sp: continue
        if Q==AD: cands.append(('V',a))
    for a in [2*min(j for _,j in P)-1, 2*max(j for _,j in P)+1]:
        Q={(i,a-j) for i,j in P}
        if Q&Sp: continue
        if Q==AD: cands.append(('H',a))
    return cands
